import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.B3IQijK_.js";const u=JSON.parse('{"title":"Research and Ideas","description":"Capture, shape, park, and advance Trading Office ideas without losing their evidence or history.","frontmatter":{"title":"Research and Ideas","description":"Capture, shape, park, and advance Trading Office ideas without losing their evidence or history.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/ideas"}]]},"headers":[],"relativePath":"trading-office/ideas.md","filePath":"trading-office/ideas.md"}'),n={name:"trading-office/ideas.md"};function r(o,e,l,d,p,h){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="research-and-ideas" tabindex="-1">Research and Ideas <a class="header-anchor" href="#research-and-ideas" aria-label="Permalink to &quot;Research and Ideas&quot;">​</a></h1><p>The Idea Backlog is the starting point for every Trading Office strategy. Use it to capture a rough observation, shape it into a falsifiable hypothesis, or send it to Strategy Lab for testing.</p><p>Idea records remain scoped to the active trading book and employee. Captured, in-flight, rejected, validated, and parked ideas remain searchable as part of the strategy&#39;s history.</p><h2 id="open-the-idea-backlog" tabindex="-1">Open the Idea Backlog <a class="header-anchor" href="#open-the-idea-backlog" aria-label="Permalink to &quot;Open the Idea Backlog&quot;">​</a></h2><p>From a Trading Office pane, run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ideas</span></span></code></pre></div><p>The menu has three views:</p><table tabindex="0"><thead><tr><th>View</th><th>What it contains</th></tr></thead><tbody><tr><td><strong>Capture</strong></td><td>A one-line input for a new idea</td></tr><tr><td><strong>Backlog</strong></td><td>Captured and in-flight ideas</td></tr><tr><td><strong>Concluded</strong></td><td>Validated, rejected, or parked ideas with their evidence</td></tr></tbody></table><p>Ideas require an active Trading Office employee and book. This keeps the research record attached to the office that owns the work.</p><h2 id="capture-first-parameterize-later" tabindex="-1">Capture first, parameterize later <a class="header-anchor" href="#capture-first-parameterize-later" aria-label="Permalink to &quot;Capture first, parameterize later&quot;">​</a></h2><p>A useful capture states an observation or suspected relationship. It does not need to arrive as a finished strategy.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Breakouts after a narrow opening range may hold better when volume is elevated.</span></span></code></pre></div><p>Avoid hiding several unrelated claims in one idea. A smaller claim is easier to falsify and easier to improve later without changing everything at once.</p><p>After saving it, choose:</p><ul><li><strong>Shape with me</strong> to clarify the hypothesis.</li><li><strong>Test it now</strong> to send the original sentence directly to Strategy Lab.</li><li><strong>Keep in backlog</strong> to return later.</li></ul><h2 id="shape-a-falsifiable-hypothesis" tabindex="-1">Shape a falsifiable hypothesis <a class="header-anchor" href="#shape-a-falsifiable-hypothesis" aria-label="Permalink to &quot;Shape a falsifiable hypothesis&quot;">​</a></h2><p>Shaping is a short conversation before any experiment is approved. tradecli asks one focused question at a time and concentrates on the choices that are genuinely unresolved:</p><ol><li>What exact event triggers entry, and on which bar?</li><li>Which symbols or universe and timeframe does the claim cover?</li><li>What target, stop, or time rule ends the trade?</li><li>What result would make you reject the claim?</li></ol><p>The resulting shape is recorded as a compact block:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Claim</span></span>
<span class="line"><span>Entry</span></span>
<span class="line"><span>Exit</span></span>
<span class="line"><span>Sweep candidates</span></span>
<span class="line"><span>Scope</span></span>
<span class="line"><span>Falsified if</span></span></code></pre></div><p>If a similar strategy already exists in the Strategy Library, the shaping flow can surface the overlap so the next test becomes an intentional improvement rather than an accidental duplicate.</p><div class="tip custom-block"><p class="custom-block-title">A practical test</p><p>A hypothesis is ready when another person could implement the same entry and exit, run it on the named scope, and tell you what result would count against it.</p></div><h2 id="send-an-idea-to-strategy-lab" tabindex="-1">Send an idea to Strategy Lab <a class="header-anchor" href="#send-an-idea-to-strategy-lab" aria-label="Permalink to &quot;Send an idea to Strategy Lab&quot;">​</a></h2><p>Open the idea in <strong>Backlog</strong> and choose <strong>Send to Lab</strong>. The idea record is carried into the experiment so its plan, job, verdict, and later strategy version can be traced back to the original observation.</p><p>Sending an idea does not bypass the evidence gates. Strategy Lab still has to:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BUILD → PLAN → RUN → JUDGE → PROMOTE</span></span></code></pre></div><p>Nothing runs until you review and approve the experiment plan. See <a href="./strategy-lab">Test in Strategy Lab</a>.</p><h2 id="keep-park-or-conclude" tabindex="-1">Keep, park, or conclude <a class="header-anchor" href="#keep-park-or-conclude" aria-label="Permalink to &quot;Keep, park, or conclude&quot;">​</a></h2><ul><li><strong>Keep in backlog</strong> when the idea is interesting but not ready to test.</li><li><strong>Park</strong> when you want to conclude it without testing. Parking does not delete it.</li><li>A tested idea moves into the concluded history with its recorded verdict and evidence.</li></ul><p>Use <strong>Snapshot</strong> on an idea to place its text, source, capture time, status, and linked experiment identifiers into scrollback without asking AI to reconstruct them.</p><h2 id="a-useful-idea-template" tabindex="-1">A useful idea template <a class="header-anchor" href="#a-useful-idea-template" aria-label="Permalink to &quot;A useful idea template&quot;">​</a></h2><p>Use this as a thinking aid, not a form you must complete before capture:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Observation: What recurring behavior did I notice?</span></span>
<span class="line"><span>Mechanism: Why might it exist?</span></span>
<span class="line"><span>Trigger: What event would create an entry?</span></span>
<span class="line"><span>Scope: Which market, symbols, and timeframe?</span></span>
<span class="line"><span>Exit: What closes or invalidates the trade?</span></span>
<span class="line"><span>Falsified if: What evidence would make me abandon the claim?</span></span></code></pre></div><p>The mechanism can remain uncertain. The trigger, scope, exit, and falsification rule cannot remain ambiguous when the experiment is approved.</p><h2 id="principles-to-keep" tabindex="-1">Principles to keep <a class="header-anchor" href="#principles-to-keep" aria-label="Permalink to &quot;Principles to keep&quot;">​</a></h2><ul><li><strong>An idea is not a strategy version.</strong> It becomes one only after a promising experiment is promoted.</li><li><strong>Rejected is a useful result.</strong> It prevents the same unsupported claim from returning as if it were new.</li><li><strong>One change deserves one child hypothesis.</strong> Improvements should preserve the parent and state exactly what changed.</li><li><strong>The record outranks the chat.</strong> The durable idea, plan, result, and review are the strategy&#39;s history.</li></ul><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li>Run the complete loop → <a href="./quickstart">Your First Strategy</a></li><li>Design and approve the test → <a href="./strategy-lab">Test in Strategy Lab</a></li><li>Turn paper evidence into a decision → <a href="./review">Review and Improve</a></li></ul>`,38)])])}const g=a(n,[["render",r]]);export{u as __pageData,g as default};
